//go:build dashboard_bundle

package control

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"io"
)

// compressedHelper is generated by build-dashboard.ps1 before compiling the packaged dashboard.
//
//go:embed helper-linux-amd64.gz
var compressedHelper []byte

// bundledHelper expands the bounded release artifact; an invalid bundle is rejected before SSH login.
func bundledHelper() []byte {
	reader, err := gzip.NewReader(bytes.NewReader(compressedHelper))
	if err != nil {
		return nil
	}
	defer reader.Close()
	binary, err := io.ReadAll(io.LimitReader(reader, helperBinaryMax+1))
	if err != nil || validateHelperBinary(binary) != nil {
		return nil
	}
	return binary
}
